struct database_vec2_t {
    union {
        struct { float x, y; };
        float v[2];
    };

    database_vec2_t() {}
    database_vec2_t(float x_value, float y_value)
    {
        x = x_value;
        y = y_value;
    }
    database_vec2_t(database_vec2_t *other)
    {
        memcpy(v, other->v, 2);
    }

    database_vec2_t operator-(const database_vec2_t &other)
    {
        return database_vec2_t(x - other.x, y - other.y);
    }

    database_vec2_t operator+(const database_vec2_t &other)
    {
        return database_vec2_t(x + other.x, y + other.y);
    }

    database_vec2_t &operator+=(const database_vec2_t &other)
    {
        x += other.x;
        y += other.y;
        return *this;
    }

    database_vec2_t &operator-=(const database_vec2_t &other)
    {
        x -= other.x;
        y -= other.y;
        return *this;
    }

    database_vec2_t &operator*=(float scalar)
    {
        x *= scalar;
        y *= scalar;
        return *this;
    }

    database_vec2_t operator-()
    {
        return database_vec2_t(-x, -y);
    }

    bool operator==(const database_vec2_t &other)
    {
        return x == other.x && y == other.y;
    }

    bool operator!=(const database_vec2_t &other)
    {
        return x != other.x || y != other.y;
    }
};
